1	import { useQuery } from '@tanstack/react-query';
2	import { asString, useSearchParam } from '../../url/useSearchParam';
3	import { ClientRow } from '../../slots/defs/clientRow';
4	import {
5	  CLIENT_SEARCH_PARAM,
6	  CLIENT_SORT_PARAM,
7	  clientsKey,
8	  clientsOutstandingKey,
9	  fetchClients,
10	  fetchClientsOutstanding,
11	  matchesClientSearch,
12	} from './queries';
13	
14	// The list. Queries for itself under ['clients'] — never handed its data by a parent (CLAUDE.md
15	// rule 5). The search box owns the filter text in the URL; the list reads the same key (rule 4) and
16	// filters the already-loaded rows. The sort control owns the `clientSort` key; the list reads it and
17	// the outstanding amounts (its own query) to order the rows. Empty state and table carry the stable
18	// data-testid contract.
19	export function ClientsTable() {
20	  const { data: clients } = useQuery({ queryKey: clientsKey, queryFn: fetchClients });
21	  const { data: outstanding } = useQuery({
22	    queryKey: clientsOutstandingKey,
23	    queryFn: fetchClientsOutstanding,
24	  });
25	  const [query] = useSearchParam(CLIENT_SEARCH_PARAM, asString);
26	  const [sort] = useSearchParam(CLIENT_SORT_PARAM, asString);
27	
28	  if (!clients) {
29	    return null;
30	  }
31	
32	  if (clients.length === 0) {
33	    return <p data-testid="clients-empty">No clients yet.</p>;
34	  }
35	
36	  // Owed per client, keyed by id, for the 'outstanding' order (0 when not yet loaded or unknown).
37	  const owedById = new Map((outstanding ?? []).map((o) => [o.clientId, Number(o.outstanding)]));
38	  const owed = (clientId: number) => owedById.get(clientId) ?? 0;
39	
40	  const visible = clients
41	    .filter((client) => matchesClientSearch(client, query))
42	    .sort((a, b) =>
43	      sort === 'outstanding'
44	        ? owed(b.id) - owed(a.id)
45	        : a.name.localeCompare(b.name),
46	    );
47	
48	  return (
